%[text] ## 2. Data Preparation
%[text] ### **2.1 Unit Conversion**
%[text] Pressure: bar to kPa and Concentration: ppm to vol.%
converted = AuxFcn_ConvertVH2DUnits_001(campaign);

conversionOverviewTable = converted.overview;
conversionSummaryTable = unique(conversionOverviewTable(:, ...
    {'Stream','RawUnit','SourceUnit','SourceUnitEvidence', ...
    'TargetUnit','Factor','Status','Rule'}), 'rows');
disp(conversionSummaryTable); %[output:57fcf843]
%[text] ### **2.2 Time Vectors Alignment**
%[text] Trigger at 4V define the zero time
aligned = AuxFcn_AlignVH2DTimeVectors_001(converted, ...
    TriggerThreshold_V=4, ...
    ReferenceStreams="DAQ_1", ...
    AlignStreams=["DAQ_2_3","DAQ_4"]);

alignmentOverviewTable = aligned.alignmentOverview;
alignmentSummaryTable = alignmentOverviewTable( ...
    ismember(alignmentOverviewTable.RootStream, ["DAQ_1","DAQ_2_3","DAQ_4"]), ...
    {'GroupId','RunId','Stream','TriggerColumn','TriggerChannel', ...
    'TriggerTime_source_s','AppliedShift_s','Status'});
disp(alignmentSummaryTable);

