%[text] ## Multi-Plot
% Plot four runs in a 2x2 tiled layout, each tile with its own left/right yyaxis
runs = { run_Wk22_02_01, run_Wk22_02_02, run_Wk22_02_03, run_Wk22_02_04 };
h2VolPct = [18, 18, 20, 20];
daq4PressureNames = ["P7_7061B", "P3_7061B"];
daq4TriggerName = "5280A_TriggerIn";
nRuns = numel(runs);

figure;
t = tiledlayout(2,2,'TileSpacing','compact','Padding','compact');
set(gcf,'Color','w');

for k = 1:nRuns
    runK = runs{k};

    % Extract signals (safety: skip if missing)
    if isempty(runK) || ~isfield(runK,'DAQ_1') || ~isfield(runK,'DAQ_4')
        warning('Run %d data missing - skipping tile.', k);
        continue;
    end

    t1 = runK.DAQ_1.t;
    y1_1 = runK.DAQ_1.signal(:,1);   % pressure DAQ-1
    y1_2 = runK.DAQ_1.signal(:,2);   % trigger DAQ-1

    % DAQ-4 channel order changes between runs. Select by raw channel name.
    idxP4 = find(ismember(runK.DAQ_4.channels, daq4PressureNames), 1);
    idxT4 = find(runK.DAQ_4.channels == daq4TriggerName, 1);

    if isempty(idxP4) || isempty(idxT4)
        warning('Run %d DAQ-4 pressure/trigger channel not found - skipping tile.', k);
        continue;
    end

    t2 = runK.DAQ_4.t;
    y2_1 = runK.DAQ_4.signal(:,idxP4);   % pressure DAQ-4
    y2_2 = runK.DAQ_4.signal(:,idxT4);   % trigger DAQ-4

    ax = nexttile;                     % get tile axes

    % Left axis: pressures
    yyaxis(ax, 'left');
    hP1 = plot(ax, t1, y1_1, '-', 'Color', LUBlue,   'LineWidth', 0.7); hold(ax,'on');
    hP2 = plot(ax, t2, y2_1, '-', 'Color', LUCopper, 'LineWidth', 0.7);
    ylabel(ax, 'Overpressure [bar]', 'Interpreter','latex');
    ax.YColor = 'k';                    % left axis tick/label color

    % Right axis: triggers
    yyaxis(ax, 'right');
    hT1 = plot(ax, t1, y1_2, '-', 'Color', LUBlue_Light,   'LineWidth', 0.7);
    hT2 = plot(ax, t2, y2_2, '-', 'Color', LUCopper_Light, 'LineWidth', 0.7);
    ylabel(ax, 'Trigger Voltage [V]', 'Interpreter','latex');
    ax.YColor = LUBlue_Light;           % right axis tick/label color

    xlabel(ax, 'Time [s]', 'Interpreter','latex');

    % Title (escape percent for latex)
    runName = sprintf('Run Wk22-02-0%d', k);
    ttl = { ...
        sprintf('%s ( $H_2$ %g vol.\\%% )', runName, h2VolPct(k)), ...
        'Pressure (Flush Mounted Sensors) and Trigger Signal' ...
        };
    title(ax, ttl, 'Interpreter','latex');

    % Legend per tile: use handles in desired order
    legend(ax, [hP1, hP2, hT1, hT2], ...
        {'Pressure (DAQ-1)','Pressure (DAQ-4)','Trigger (DAQ-1)','Trigger (DAQ-4)'}, ...
        'Location','northeast', 'Interpreter','latex');

    grid(ax,'on');
    hold(ax,'off');
end

sgtitle(t, 'Group VH2D-Wk22-02: Pressure $\&$ Trigger ', 'Interpreter','latex');


